<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);
if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user){Security::destroySession();header('Location: login.php');exit;}if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'users.manage')){http_response_code(403);exit('Administrator account-management permission required.');}}
catch(Throwable $e){error_log('User manager: '.$e->getMessage());http_response_code(503);exit('Account management is unavailable.');}
$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);$error='Session expired. Refresh and try again.';}
 else try{$id=(int)($_POST['user_id']??0);$status=(string)($_POST['account_status']??'');if($id<1||$id===(int)$user['user_id'])throw new InvalidArgumentException('Choose another valid account. You cannot change your own account here.');if(!in_array($status,['ACTIVE','SUSPENDED','DISABLED'],true))throw new InvalidArgumentException('Choose a valid account status.');$q=$db->prepare('SELECT account_status,email_verified_at,account_type FROM users WHERE user_id=:id FOR UPDATE');$db->beginTransaction();$q->execute(['id'=>$id]);$target=$q->fetch(PDO::FETCH_ASSOC);if(!$target)throw new InvalidArgumentException('Account not found.');if($status==='ACTIVE'&&empty($target['email_verified_at']))throw new InvalidArgumentException('An account without verified email cannot be activated.');if($target['account_type']==='ADMINISTRATOR'&&$status!=='ACTIVE')throw new InvalidArgumentException('Use a separate approved administrative procedure to disable another administrator.');$u=$db->prepare('UPDATE users SET account_status=:status,failed_login_count=0,locked_until=NULL,updated_at=NOW() WHERE user_id=:id');$u->execute(['status'=>$status,'id'=>$id]);AuditLogger::record($db,(int)$user['user_id'],'USER_ACCOUNT_STATUS_CHANGED','user',$id,['old_status'=>$target['account_status'],'new_status'=>$status]);$db->commit();$message='Account status updated.';
 }catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('User status update: '.$e->getMessage());$error='Unable to update the account.';}
}
$rows=$db->query('SELECT u.user_id,u.username,u.email,u.account_type,u.account_status,u.email_verified_at,u.failed_login_count,u.locked_until,u.created_at,r.role_code FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.user_id LEFT JOIN roles r ON r.role_id=ur.role_id ORDER BY u.created_at DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Account Management','Review and manage portal account status.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">ADMINISTRATIVE CONTROL</p><h1>Account Management</h1><p>Review registered accounts, email verification, and account status.</p></div></section><section class="section"><?php if($message): ?><div class="notice info" role="status"><?= Security::e($message) ?></div><?php endif; ?><?php if($error): ?><div class="notice warning" role="alert"><?= Security::e($error) ?></div><?php endif; ?><div class="notice warning"><b>Administrative safeguard</b><p>This demonstration page cannot change your own account or disable another Administrator. Do not use it as a substitute for an approved account-provisioning policy.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Username</th><th>Email</th><th>Type / Role</th><th>Verification</th><th>Status</th><th>Failed logins</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Security::e($r['username']) ?></td><td><?= Security::e($r['email']) ?></td><td><?= Security::e($r['account_type'].' / '.($r['role_code']??'No role')) ?></td><td><?= $r['email_verified_at']?'Verified':'Pending' ?></td><td><?= Security::e($r['account_status']) ?></td><td><?= (int)$r['failed_login_count'] ?><?= $r['locked_until']?' · Locked':'' ?></td><td><?php if((int)$r['user_id']!==(int)$user['user_id']&&$r['account_type']!=='ADMINISTRATOR'): ?><form method="post" class="workflow-actions"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="user_id" value="<?= (int)$r['user_id'] ?>"><select name="account_status"><option value="ACTIVE" <?= $r['account_status']==='ACTIVE'?'selected':'' ?>>Active</option><option value="SUSPENDED" <?= $r['account_status']==='SUSPENDED'?'selected':'' ?>>Suspend</option><option value="DISABLED" <?= $r['account_status']==='DISABLED'?'selected':'' ?>>Disable</option></select><button type="submit" class="action-primary">Save</button></form><?php else: ?>Protected<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><?php pageFooter();
